      "svg": "<svg viewBox=\"0 0 1100 1100\" xmlns=\"http://www.w3.org/2000/svg\"><rect width=\"1100\" height=\"1100\" fill=\"#1a1a2e\"/><text x=\"550\" y=\"120\" font-family=\"sans-serif\" font-size=\"32\" fill=\"#ffd700\" text-anchor=\"middle\">2-Year CEU Cycle</text><circle cx=\"550\" cy=\"550\" r=\"220\" fill=\"none\" stroke=\"#6366f1\" stroke-width=\"8\"/><path d=\"M 550 330 A 220 220 0 0 1 770 550\" fill=\"none\" stroke=\"#10b981\" stroke-width=\"16\"/><path d=\"M 770 550 A 220 220 0 0 1 550 770\" fill=\"none\" stroke=\"#f59e0b\" stroke-width=\"16\"/><path d=\"M 550 770 A 220 220 0 0 1 330 550\" fill=\"none\" stroke=\"#0ea5e9\" stroke-width=\"16\"/><path d=\"M 330 550 A 220 220 0 0 1 550 330\" fill=\"none\" stroke=\"#ec4899\" stroke-width=\"16\"/><text x=\"550\" y=\"540\" font-family=\"sans-serif\" font-size=\"26\" fill=\"#ffffff\" text-anchor=\"middle\">Earn CEUs</text><text x=\"550\" y=\"580\" font-family=\"sans-serif\" font-size=\"26\" fill=\"#ffffff\" text-anchor=\"middle\">- report -</text><text x=\"550\" y=\"620\" font-family=\"sans-serif\" font-size=\"26\" fill=\"#ffffff\" text-anchor=\"middle\">renew</text><text x=\"550\" y=\"860\" font-family=\"sans-serif\" font-size=\"22\" fill=\"#888888\" text-anchor=\"middle\">Continuous learning keeps you current</text></svg>",
